
/* Source style block 1 */

@import url('https://fonts.googleapis.com/css2?family=Oswald:wght@300;400;600;700&family=Source+Serif+4:ital,wght@0,300;0,400;0,600;1,300&family=Share+Tech+Mono&display=swap');

:root {
  --bg: #f4f2ee;
  --white: #ffffff;
  --ink: #1a1a1a;
  --ink-light: #4a4a4a;
  --blue: #0d2240;
  --blue-mid: #1a3a6a;
  --blue-light: #2a5a9a;
  --gold: #c8a820;
  --gold-light: #e8c840;
  --border: #d0ccc4;
  --red: #8b1a1a;
}

* { margin: 0; padding: 0; box-sizing: border-box; }

body {
  font-family: 'Source Serif 4', serif;
  background: var(--bg);
  color: var(--ink);
  min-height: 100vh;
  overflow-x: hidden;
}

html {
  overflow-x: hidden;
}

/* ===== DISSOLVED BANNER ===== */
.dissolved-banner {
  background: var(--red);
  color: #fff;
  text-align: center;
  padding: 7px;
  font-family: 'Share Tech Mono', monospace;
  font-size: 10px;
  letter-spacing: 0.3em;
}

.fiction-banner {
  color: #6a6a6a;
  text-align: center;
  font-family: 'Share Tech Mono', monospace;
  font-size: 9px;
  letter-spacing: 0.15em;
  padding-top: 8px;
  margin-top: 8px;
  border-top: 1px solid rgba(255,255,255,0.08);
}

.editor-notice-banner {
  background: #0d1c2c;
  color: #6a8aa8;
  text-align: center;
  padding: 6px 10px;
  font-family: 'Share Tech Mono', monospace;
  font-size: 9px;
  letter-spacing: 0.12em;
  border-bottom: 1px solid #1a3050;
}

/* ===== HEADER ===== */
header {
  background: var(--blue);
  border-bottom: 3px solid var(--gold);
}

.header-inner {
  max-width: 1100px;
  margin: 0 auto;
  padding: 20px 30px;
  display: flex;
  align-items: center;
  gap: 24px;
}

.logo-wrap {
  background: #ffffff;
  border-radius: 12px;
  padding: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.logo-wrap img {
  width: 140px;
  height: auto;
  display: block;
}

.header-text h1 {
  font-family: 'Oswald', sans-serif;
  font-size: 32px;
  font-weight: 700;
  color: #e8eef8;
  letter-spacing: 0.1em;
}

.header-text .tagline {
  font-family: 'Share Tech Mono', monospace;
  font-size: 10px;
  color: #6a8aaa;
  letter-spacing: 0.2em;
  margin-top: 4px;
}

.header-right {
  margin-left: auto;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 8px;
}

.lang-toggle {
  display: flex;
  gap: 6px;
}

.lang-btn {
  background: transparent;
  border: 1px solid #2a4a6a;
  color: #6a8aaa;
  font-family: 'Share Tech Mono', monospace;
  font-size: 10px;
  padding: 4px 10px;
  cursor: pointer;
  letter-spacing: 0.1em;
  transition: all 0.2s;
}

.lang-btn.active, .lang-btn:hover {
  border-color: var(--gold);
  color: var(--gold);
}

.employee-btn {
  background: transparent;
  border: 1px solid var(--gold);
  color: var(--gold);
  font-family: 'Share Tech Mono', monospace;
  font-size: 10px;
  padding: 6px 14px;
  cursor: pointer;
  letter-spacing: 0.15em;
  transition: all 0.2s;
}

.employee-btn:hover {
  background: var(--gold);
  color: var(--blue);
}

/* ===== NAV ===== */
nav {
  background: var(--blue-mid);
  border-bottom: 1px solid #1a3a5a;
  overflow-x: auto;
  overflow-y: hidden;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
}

nav::-webkit-scrollbar { display: none; }

.nav-inner {
  max-width: 1100px;
  margin: 0 auto;
  display: flex;
  width: max-content;
  min-width: 100%;
}

nav a {
  padding: 14px 24px;
  color: #8aaac8;
  text-decoration: none;
  font-family: 'Oswald', sans-serif;
  font-size: 12px;
  font-weight: 400;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  border-right: 1px solid #1a3050;
  transition: all 0.2s;
  cursor: pointer;
  flex-shrink: 0;
  text-align: center;
  white-space: nowrap;
}

nav a:hover, nav a.active {
  background: #1a2a4a;
  color: #e8eef8;
}

/* ===== MAIN CONTENT ===== */
#publicLayer {
  display: flex;
  flex-direction: column;
  height: 100vh;
  overflow: hidden;
}

#publicLayer > header,
#publicLayer > nav,
#publicLayer > .dissolved-banner,
#publicLayer > .editor-notice-banner {
  flex-shrink: 0;
}

.main {
  max-width: 1100px;
  margin: 0 auto;
  padding: 40px 30px;
  width: 100%;
}

.main-scroll {
  flex: 1;
  overflow-y: auto;
  overflow-x: hidden;
}

.page { display: none; }
.page.active { display: block; }

/* ===== HERO ===== */
.hero {
  background: var(--blue);
  color: #e8eef8;
  padding: 60px 50px;
  margin-bottom: 40px;
  position: relative;
  overflow: hidden;
}

.hero::before {
  content: '';
  position: absolute;
  inset: 0;
  background: repeating-linear-gradient(
    90deg,
    transparent,
    transparent 60px,
    rgba(255,255,255,0.02) 60px,
    rgba(255,255,255,0.02) 61px
  );
}

.hero-label {
  font-family: 'Share Tech Mono', monospace;
  font-size: 10px;
  letter-spacing: 0.3em;
  color: var(--gold);
  margin-bottom: 16px;
  text-transform: uppercase;
}

.hero h2 {
  font-family: 'Oswald', sans-serif;
  font-size: clamp(24px, 4vw, 42px);
  font-weight: 600;
  line-height: 1.2;
  margin-bottom: 20px;
  position: relative;
}

.hero p {
  font-size: 15px;
  line-height: 1.8;
  color: #8aaac8;
  max-width: 600px;
  position: relative;
}

.hero-since {
  position: absolute;
  right: 50px;
  bottom: 30px;
  font-family: 'Oswald', sans-serif;
  font-size: 80px;
  font-weight: 700;
  color: rgba(255,255,255,0.04);
  letter-spacing: -2px;
}

/* ===== STATS BAR ===== */
.stats-bar {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
  gap: 1px;
  background: var(--border);
  border: 1px solid var(--border);
  margin-bottom: 40px;
}

.stat-item {
  background: var(--white);
  padding: 20px 24px;
  text-align: center;
}

.stat-number {
  font-family: 'Oswald', sans-serif;
  font-size: 28px;
  font-weight: 700;
  color: var(--blue);
  display: block;
}

.stat-label {
  font-family: 'Share Tech Mono', monospace;
  font-size: 9px;
  color: var(--ink-light);
  letter-spacing: 0.15em;
  text-transform: uppercase;
  margin-top: 4px;
  display: block;
}

/* ===== CONTENT GRID ===== */
.content-grid {
  display: grid;
  grid-template-columns: 2fr 1fr;
  gap: 30px;
  margin-bottom: 40px;
}

@media (max-width: 700px) {
  .content-grid { grid-template-columns: 1fr; }
  .hero { padding: 30px 24px; }
  .hero-since { display: none; }
  .header-inner { padding: 12px 16px; gap: 12px; }
  .logo-wrap img { width: 90px; }
  .header-text h1 { font-size: 22px; }
}

/* ===== SECTION HEADER ===== */
.section-header {
  display: flex;
  align-items: baseline;
  gap: 16px;
  margin-bottom: 20px;
  padding-bottom: 10px;
  border-bottom: 2px solid var(--blue);
}

.section-header h3 {
  font-family: 'Oswald', sans-serif;
  font-size: 16px;
  font-weight: 600;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--blue);
}

.section-header span {
  font-family: 'Share Tech Mono', monospace;
  font-size: 9px;
  color: var(--ink-light);
  letter-spacing: 0.2em;
}

/* ===== CARDS ===== */
.card {
  background: var(--white);
  border: 1px solid var(--border);
  padding: 24px;
  margin-bottom: 16px;
}

.card-label {
  font-family: 'Share Tech Mono', monospace;
  font-size: 9px;
  letter-spacing: 0.2em;
  color: var(--gold);
  text-transform: uppercase;
  margin-bottom: 8px;
}

.card h4 {
  font-family: 'Oswald', sans-serif;
  font-size: 15px;
  font-weight: 600;
  color: var(--blue);
  margin-bottom: 8px;
}

.card p {
  font-size: 13px;
  line-height: 1.7;
  color: var(--ink-light);
}

/* ===== SIDEBAR ===== */
.sidebar-box {
  background: var(--blue);
  color: #e8eef8;
  padding: 24px;
  margin-bottom: 16px;
}

.sidebar-box h4 {
  font-family: 'Oswald', sans-serif;
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--gold);
  margin-bottom: 16px;
  padding-bottom: 8px;
  border-bottom: 1px solid #2a4a6a;
}

.sidebar-box p {
  font-size: 12px;
  line-height: 1.7;
  color: #8aaac8;
}

.sidebar-item {
  padding: 10px 0;
  border-bottom: 1px solid #1a3050;
  font-family: 'Share Tech Mono', monospace;
  font-size: 10px;
  color: #8aaac8;
  letter-spacing: 0.1em;
}

.sidebar-item:last-child { border-bottom: none; }

.sidebar-item strong {
  color: #e8eef8;
  display: block;
  margin-bottom: 2px;
}

/* ===== HISTORY PAGE ===== */
.history-lead {
  font-size: 17px;
  line-height: 1.8;
  color: var(--ink-light);
  margin-bottom: 30px;
  padding-bottom: 30px;
  border-bottom: 1px solid var(--border);
}

.timeline {
  position: relative;
  padding-left: 30px;
}

.timeline::before {
  content: '';
  position: absolute;
  left: 6px;
  top: 0;
  bottom: 0;
  width: 2px;
  background: var(--border);
}

.timeline-item {
  position: relative;
  margin-bottom: 32px;
}

.timeline-item::before {
  content: '';
  position: absolute;
  left: -27px;
  top: 6px;
  width: 10px;
  height: 10px;
  background: var(--blue);
  border: 2px solid var(--gold);
}

.timeline-year {
  font-family: 'Oswald', sans-serif;
  font-size: 13px;
  font-weight: 700;
  color: var(--gold);
  letter-spacing: 0.1em;
  margin-bottom: 4px;
}

.timeline-item h4 {
  font-family: 'Oswald', sans-serif;
  font-size: 15px;
  color: var(--blue);
  margin-bottom: 6px;
}

.timeline-item p {
  font-size: 13px;
  line-height: 1.7;
  color: var(--ink-light);
}

.highlight-code {
  font-family: 'Share Tech Mono', monospace;
  background: var(--blue);
  color: var(--gold);
  padding: 1px 6px;
  font-size: 11px;
  letter-spacing: 0.1em;
}

/* ===== DEPARTMENTS ===== */
.dept-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 20px;
}

.dept-card {
  background: var(--white);
  border: 1px solid var(--border);
  border-top: 3px solid var(--blue);
  padding: 24px;
}

.dept-icon {
  font-size: 24px;
  margin-bottom: 12px;
  display: block;
}

.dept-card h4 {
  font-family: 'Oswald', sans-serif;
  font-size: 14px;
  font-weight: 600;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--blue);
  margin-bottom: 10px;
}

.dept-card p {
  font-size: 12px;
  line-height: 1.7;
  color: var(--ink-light);
}

/* ===== NEWS ===== */
.news-item {
  background: var(--white);
  border: 1px solid var(--border);
  padding: 24px;
  margin-bottom: 16px;
  display: flex;
  gap: 20px;
}

.news-date {
  font-family: 'Share Tech Mono', monospace;
  font-size: 10px;
  color: var(--ink-light);
  letter-spacing: 0.1em;
  min-width: 80px;
  padding-top: 3px;
}

.news-content h4 {
  font-family: 'Oswald', sans-serif;
  font-size: 15px;
  color: var(--blue);
  margin-bottom: 6px;
}

.news-content p {
  font-size: 12px;
  line-height: 1.6;
  color: var(--ink-light);
}

.news-tag {
  display: inline-block;
  font-family: 'Share Tech Mono', monospace;
  font-size: 8px;
  letter-spacing: 0.15em;
  padding: 2px 8px;
  border: 1px solid currentColor;
  margin-top: 8px;
  color: var(--blue-light);
}

/* ===== CAREERS ===== */
.careers-intro {
  background: var(--blue);
  color: #e8eef8;
  padding: 40px;
  margin-bottom: 30px;
}

.careers-intro h3 {
  font-family: 'Oswald', sans-serif;
  font-size: 22px;
  color: var(--gold);
  margin-bottom: 12px;
}

.careers-intro p {
  font-size: 13px;
  line-height: 1.8;
  color: #8aaac8;
  max-width: 600px;
}

.careers-form {
  background: var(--white);
  border: 1px solid var(--border);
  padding: 32px;
  max-width: 600px;
}

.careers-form h4 {
  font-family: 'Oswald', sans-serif;
  font-size: 16px;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--blue);
  margin-bottom: 24px;
  padding-bottom: 12px;
  border-bottom: 2px solid var(--blue);
}

.form-group {
  margin-bottom: 20px;
}

.form-group label {
  display: block;
  font-family: 'Share Tech Mono', monospace;
  font-size: 10px;
  letter-spacing: 0.15em;
  color: var(--ink-light);
  text-transform: uppercase;
  margin-bottom: 6px;
}

.form-group input,
.form-group select,
.form-group textarea {
  width: 100%;
  padding: 10px 14px;
  border: 1px solid var(--border);
  background: var(--bg);
  font-family: 'Source Serif 4', serif;
  font-size: 13px;
  color: var(--ink);
  outline: none;
  transition: border-color 0.2s;
}

.form-group input:focus,
.form-group select:focus,
.form-group textarea:focus {
  border-color: var(--blue);
}

.form-group textarea { height: 80px; resize: vertical; }

.form-submit {
  background: var(--blue);
  color: #e8eef8;
  border: none;
  padding: 12px 32px;
  font-family: 'Oswald', sans-serif;
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  cursor: pointer;
  transition: all 0.2s;
  width: 100%;
  margin-top: 8px;
}

.form-submit:hover { background: var(--blue-mid); }

.form-success {
  display: none;
  background: #0a1a0a;
  border: 1px solid #2a5a2a;
  padding: 20px;
  margin-top: 16px;
  font-family: 'Share Tech Mono', monospace;
  font-size: 11px;
  color: #4a8a4a;
  letter-spacing: 0.1em;
  line-height: 1.8;
}

/* ===== EMPLOYEE PORTAL ===== */
.portal-overlay {
  display: none;
  position: fixed;
  inset: 0;
  background: rgba(20, 5, 8, 0.95);
  z-index: 1000;
  align-items: center;
  justify-content: center;
}

.portal-overlay.visible { display: flex; }

.portal-box {
  background: #f7f0f1;
  border: 1px solid #8b1a2a;
  padding: 40px;
  max-width: 420px;
  width: 90%;
  border-radius: 4px;
  box-shadow: 0 8px 32px rgba(100,0,20,0.15);
}

.portal-header {
  font-family: 'Share Tech Mono', monospace;
  font-size: 9px;
  color: #8b1a2a;
  letter-spacing: 0.3em;
  text-transform: uppercase;
  margin-bottom: 24px;
  padding-bottom: 16px;
  border-bottom: 1px solid #c8a0a8;
}

.portal-title {
  font-family: 'Oswald', sans-serif;
  font-size: 22px;
  color: #6b0f1e;
  letter-spacing: 0.1em;
  margin-bottom: 8px;
}

.portal-sub {
  font-family: 'Share Tech Mono', monospace;
  font-size: 10px;
  color: #9a5a65;
  letter-spacing: 0.15em;
  margin-bottom: 28px;
}

.portal-input-wrap {
  position: relative;
  margin-bottom: 16px;
}

.portal-input {
  width: 100%;
  background: #fff5f6;
  border: 1px solid #c8a0a8;
  color: #3a1018;
  font-family: 'Share Tech Mono', monospace;
  font-size: 14px;
  letter-spacing: 0.2em;
  padding: 12px 16px;
  outline: none;
  text-transform: uppercase;
  border-radius: 2px;
}

.portal-input:focus { border-color: #8b1a2a; }

.portal-enter {
  width: 100%;
  background: #8b1a2a;
  border: 1px solid #8b1a2a;
  color: #f7f0f1;
  font-family: 'Share Tech Mono', monospace;
  font-size: 11px;
  letter-spacing: 0.25em;
  padding: 12px;
  cursor: pointer;
  text-transform: uppercase;
  transition: all 0.2s;
  border-radius: 2px;
}

.portal-enter:hover {
  background: #6b0f1e;
  border-color: #6b0f1e;
}

.portal-error {
  font-family: 'Share Tech Mono', monospace;
  font-size: 10px;
  color: #cc2233;
  letter-spacing: 0.1em;
  margin-top: 10px;
  display: none;
}

.portal-close {
  background: transparent;
  border: none;
  color: #9a7a80;
  font-family: 'Share Tech Mono', monospace;
  font-size: 10px;
  letter-spacing: 0.2em;
  cursor: pointer;
  margin-top: 16px;
  text-transform: uppercase;
  width: 100%;
  padding: 8px;
  transition: color 0.2s;
}

.portal-close:hover { color: #6b0f1e; }

/* ===== EMPLOYEE LAYER ===== */
.employee-layer {
  display: none;
  background: #0a0a08;
  min-height: 100vh;
}

.employee-layer.visible { display: block; }

.emp-hazard-strip {
  height: 6px;
  background: repeating-linear-gradient(
    135deg,
    #f0c419 0px, #f0c419 14px,
    #0a0a08 14px, #0a0a08 28px
  );
}

/* ============ INTRO SEAL SEQUENCE ============
   Locked-eye seal fades in under a verification scan, "unlocks" into
   the question-mark seal with a shockwave burst, then the whole thing
   shrinks and migrates to the header, where it remains as a permanent
   watermark next to the I.R.I.S. CORP logo. */
.emp-intro-overlay {
  position: fixed;
  inset: 0;
  z-index: 900;
  background: #0a0a08;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  pointer-events: none;
}

.emp-intro-overlay.emp-intro-done {
  display: none;
}

.emp-intro-stage {
  position: relative;
  width: min(74vw, 560px);
  height: min(74vw, 560px);
  display: flex;
  align-items: center;
  justify-content: center;
}

/* Ambient pulsing glow behind the seal */
.emp-intro-glow {
  position: absolute;
  inset: -35%;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(240,196,25,0.4) 0%, rgba(240,196,25,0) 68%);
  opacity: 0;
}

.emp-intro-overlay.emp-intro-playing .emp-intro-glow {
  animation: empIntroGlow 2.6s ease-in-out forwards;
}

@keyframes empIntroGlow {
  0%   { opacity: 0; transform: scale(0.88); }
  18%  { opacity: 0.55; transform: scale(1); }
  45%  { opacity: 0.35; transform: scale(1.02); }
  58%  { opacity: 0.5; transform: scale(1); }
  66%  { opacity: 0.95; transform: scale(1.22); }
  82%  { opacity: 0.4; transform: scale(1); }
  100% { opacity: 0; transform: scale(0.8); }
}

/* Shockwave ring bursting outward at the unlock moment */
.emp-intro-shockwave {
  position: absolute;
  inset: 6%;
  border: 2px solid #f0c419;
  border-radius: 50%;
  opacity: 0;
  transform: scale(0.85);
}

.emp-intro-overlay.emp-intro-playing .emp-intro-shockwave {
  animation: empIntroShockwave 2.6s ease-out forwards;
}

@keyframes empIntroShockwave {
  0%, 58% { opacity: 0; transform: scale(0.85); }
  63%     { opacity: 0.9; transform: scale(0.95); }
  80%     { opacity: 0; transform: scale(1.7); }
  100%    { opacity: 0; transform: scale(1.7); }
}

/* Scanline sweeping top-to-bottom across the seal during verification,
   clipped to a circular mask so it reads as a beam scanning the disc */
.emp-intro-seal-clip {
  position: absolute;
  inset: 0;
  border-radius: 50%;
  overflow: hidden;
}

.emp-intro-scanline {
  position: absolute;
  left: -10%;
  right: -10%;
  height: 4px;
  top: -8%;
  background: linear-gradient(90deg, transparent, rgba(240,196,25,0.95), transparent);
  filter: blur(0.5px);
  opacity: 0;
}

.emp-intro-overlay.emp-intro-playing .emp-intro-scanline {
  animation: empIntroScanline 2.6s linear forwards;
}

@keyframes empIntroScanline {
  0%   { top: -8%; opacity: 0; }
  6%   { opacity: 0.85; }
  50%  { top: 104%; opacity: 0.85; }
  58%  { opacity: 0; }
  100% { top: 104%; opacity: 0; }
}

.emp-intro-seal {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  opacity: 0;
}

.emp-intro-overlay.emp-intro-playing #empIntroSealLocked {
  animation: empIntroLockedSeal 2.6s ease-in-out forwards;
}

.emp-intro-overlay.emp-intro-playing #empIntroSealQuestion {
  animation: empIntroQuestionSeal 2.6s ease-in-out forwards;
}

@keyframes empIntroLockedSeal {
  0%   { opacity: 0; transform: scale(0.9); }
  18%  { opacity: 1; transform: scale(1); }
  55%  { opacity: 1; transform: scale(1); }
  64%  { opacity: 0; transform: scale(1.08) rotate(1deg); }
  100% { opacity: 0; transform: scale(1.08); }
}

@keyframes empIntroQuestionSeal {
  0%   { opacity: 0; transform: scale(1.08); }
  60%  { opacity: 0; transform: scale(1.08); }
  64%  { opacity: 0.4; transform: scale(1.02); }
  68%  { opacity: 1; transform: scale(1); }
  84%  { opacity: 1; transform: scale(1); }
  100% { opacity: 0; transform: scale(0.15); }
}

/* Animated glint sweeping diagonally across each seal, masked to its exact
   silhouette (alpha channel) so the shine only travels over the visible
   gold lines/icon rather than across a plain rectangle. */
.emp-seal-shine {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  opacity: 0;
  pointer-events: none;
  mix-blend-mode: screen;
  background: linear-gradient(115deg, transparent 15%, rgba(255,255,255,0.6) 50%, transparent 85%);
  background-repeat: no-repeat;
  background-size: 260% 260%;
  background-position: -120% -120%;
  -webkit-mask-repeat: no-repeat;
  mask-repeat: no-repeat;
  -webkit-mask-size: 100% 100%;
  mask-size: 100% 100%;
  -webkit-mask-mode: alpha;
  mask-mode: alpha;
}

.emp-seal-shine-locked {
  -webkit-mask-image: url('data:image/webp;base64,');
  mask-image: url('data:image/webp;base64,');
}

.emp-seal-shine-question {
  -webkit-mask-image: url('data:image/webp;base64,');
  mask-image: url('data:image/webp;base64,');
}

.emp-intro-overlay.emp-intro-playing .emp-seal-shine-locked {
  animation: empShineSweepLocked 2.6s ease-in-out forwards;
}

.emp-intro-overlay.emp-intro-playing .emp-seal-shine-question {
  animation: empShineSweepQuestion 2.6s ease-in-out forwards;
}

@keyframes empShineSweepLocked {
  0%, 8%  { opacity: 0; background-position: -120% -120%; }
  14%     { opacity: 0.9; }
  30%     { opacity: 0.9; background-position: 120% 120%; }
  38%, 100% { opacity: 0; background-position: 120% 120%; }
}

@keyframes empShineSweepQuestion {
  0%, 70%   { opacity: 0; background-position: -120% -120%; }
  76%       { opacity: 0.9; }
  88%       { opacity: 0.9; background-position: 120% 120%; }
  93%, 100% { opacity: 0; background-position: 120% 120%; }
}

/* Permanent header seal — hidden until the intro sequence hands off to it */
.emp-header-seal {
