/* ===== LOGS APP REDESIGN ===== */
.logs-app {
  display: flex;
  height: calc(100vh - 120px);
  min-height: 500px;
  background: #0a0a08;
  border: 1px solid #3a3522;
  overflow: hidden;
}

.logs-sidebar {
  width: 64px;
  background: #080805;
  border-right: 1px solid #3a3522;
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 12px 0;
  flex-shrink: 0;
}

.logs-sidebar-logo {
  width: 44px;
  height: 44px;
  margin-bottom: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.logs-sidebar-logo img {
  width: 40px;
  height: 40px;
  object-fit: contain;
  opacity: 0.7;
}

.logs-sidebar-divider {
  width: 36px;
  height: 1px;
  background: #3a3522;
  margin: 8px 0;
}

.logs-sidebar-btn {
  width: 44px;
  height: 44px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  border: 1px solid transparent;
  color: #8a8364;
  font-size: 18px;
  transition: all 0.2s;
  margin: 3px 0;
  position: relative;
}

.logs-sidebar-btn:hover, .logs-sidebar-btn.active {
  border-color: #8a7a2a;
  color: var(--gold);
  background: #1c1a10;
}

.logs-sidebar-btn svg {
  width: 22px;
  height: 22px;
  stroke: currentColor;
  fill: none;
  stroke-width: 1.5;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.logs-sidebar-pagination {
  margin-top: auto;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  padding-bottom: 8px;
}

.logs-page-btn {
  width: 36px;
  height: 30px;
  background: transparent;
  border: 1px solid #3a3522;
  color: #8a8364;
  cursor: pointer;
  font-family: 'Share Tech Mono', monospace;
  font-size: 14px;
  transition: all 0.2s;
  display: flex;
  align-items: center;
  justify-content: center;
}

.logs-page-btn:hover {
  border-color: var(--gold);
  color: var(--gold);
}

.logs-page-indicator {
  font-family: 'Share Tech Mono', monospace;
  font-size: 8px;
  color: #4a4530;
  letter-spacing: 0.1em;
  text-align: center;
}

.logs-main {
  flex: 1;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.logs-main-header {
  padding: 16px 20px 12px;
  border-bottom: 1px solid #3a3522;
  display: flex;
  align-items: baseline;
  justify-content: space-between;
}

.logs-main-title {
  font-family: 'Oswald', sans-serif;
  font-size: 16px;
  font-weight: 600;
  letter-spacing: 0.2em;
  color: #f0e6c0;
  text-transform: uppercase;
}

.logs-main-subtitle {
  font-family: 'Share Tech Mono', monospace;
  font-size: 9px;
  color: #8a7a2a;
  letter-spacing: 0.15em;
}

.logs-content {
  flex: 1;
  overflow-y: auto;
  padding: 12px 0;
}

.logs-content::-webkit-scrollbar {
  width: 6px;
}
.logs-content::-webkit-scrollbar-track { background: #0a0a08; }
.logs-content::-webkit-scrollbar-thumb { background: #3a3522; }

.logs-entry-row {
  padding: 12px 20px;
  border-bottom: 1px solid #1c1a10;
  cursor: pointer;
  transition: background 0.15s;
  display: flex;
  align-items: center;
  gap: 12px;
}

.logs-entry-row:hover { background: #1c1a10; }

.logs-entry-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--gold);
  flex-shrink: 0;
  opacity: 0.6;
}

.logs-entry-dot.received { background: #b8a04a; }

.logs-entry-info { flex: 1; min-width: 0; }

.logs-entry-title {
  font-family: 'Share Tech Mono', monospace;
  font-size: 11px;
  color: #f0e6c0;
  letter-spacing: 0.05em;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.logs-entry-meta {
  font-family: 'Share Tech Mono', monospace;
  font-size: 9px;
  color: #8a8364;
  letter-spacing: 0.05em;
  margin-top: 2px;
}

.logs-entry-date {
  font-family: 'Share Tech Mono', monospace;
  font-size: 9px;
  color: #4a4530;
  flex-shrink: 0;
}

.logs-empty-state {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  height: 200px;
  font-family: 'Share Tech Mono', monospace;
  font-size: 10px;
  color: #4a4530;
  letter-spacing: 0.2em;
  text-align: center;
  line-height: 2;
}

/* PANEL OVERLAY */
.logs-panel {
  display: none;
  position: absolute;
  top: 0; left: 64px; right: 0; bottom: 0;
  background: #0a0a08;
  z-index: 10;
  flex-direction: column;
}

.logs-panel.visible { display: flex; }

.logs-panel-header {
  padding: 16px 20px;
  border-bottom: 1px solid #3a3522;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.logs-panel-title {
  font-family: 'Oswald', sans-serif;
  font-size: 14px;
  font-weight: 600;
  letter-spacing: 0.2em;
  color: var(--gold);
  text-transform: uppercase;
}

.logs-panel-close {
  background: transparent;
  border: none;
  color: #8a8364;
  font-size: 16px;
  cursor: pointer;
  padding: 4px 8px;
  transition: color 0.2s;
}

.logs-panel-close:hover { color: var(--red); }

.logs-panel-body {
  flex: 1;
  overflow-y: auto;
  padding: 20px;
}

/* ADD LOG FORM */
.logs-add-field {
  margin-bottom: 14px;
}

.logs-add-label {
  font-family: 'Share Tech Mono', monospace;
  font-size: 9px;
  color: #8a8364;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  display: block;
  margin-bottom: 6px;
}

.logs-add-input {
  width: 100%;
  background: #1c1a10;
  border: 1px solid #3a3522;
  color: #f0e6c0;
  font-family: 'Share Tech Mono', monospace;
  font-size: 12px;
  padding: 10px 14px;
  outline: none;
  letter-spacing: 0.05em;
  transition: border-color 0.2s;
}

.logs-add-input:focus { border-color: var(--gold); }

.logs-add-textarea {
  width: 100%;
  height: 180px;
  background: #1c1a10;
  border: 1px solid #3a3522;
  color: #f0e6c0;
  font-family: 'Share Tech Mono', monospace;
  font-size: 12px;
  padding: 10px 14px;
  outline: none;
  resize: vertical;
  line-height: 1.7;
  transition: border-color 0.2s;
}

.logs-add-textarea:focus { border-color: var(--gold); }

.logs-save-btn {
  width: 100%;
  background: transparent;
  border: 1px solid var(--gold);
  color: var(--gold);
  font-family: 'Share Tech Mono', monospace;
  font-size: 10px;
  letter-spacing: 0.2em;
  padding: 12px;
  cursor: pointer;
  text-transform: uppercase;
  transition: all 0.2s;
}
.logs-save-btn:hover { background: var(--gold); color: #0a0a08; }

/* SETTINGS */
.logs-setting-row {
  margin-bottom: 20px;
}

.logs-setting-label {
  font-family: 'Share Tech Mono', monospace;
  font-size: 9px;
  color: #8a8364;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  display: block;
  margin-bottom: 8px;
}

.logs-color-row {
  display: flex;
  gap: 10px;
  align-items: center;
}

.logs-color-row input[type="color"] {
  width: 40px;
  height: 32px;
  border: 1px solid #3a3522;
  background: #1c1a10;
  cursor: pointer;
  padding: 2px;
}

.logs-color-row span {
  font-family: 'Share Tech Mono', monospace;
  font-size: 10px;
  color: #8a8364;
}

.logs-apply-btn {
  padding: 8px 20px;
  background: transparent;
  border: 1px solid #8a7a2a;
  color: #b8a04a;
  font-family: 'Share Tech Mono', monospace;
  font-size: 10px;
  letter-spacing: 0.15em;
  cursor: pointer;
  text-transform: uppercase;
  transition: all 0.2s;
  margin-top: 8px;
}
.logs-apply-btn:hover { border-color: var(--gold); color: var(--gold); }

/* FILES / SEND */
.logs-compose-btn {
  width: 100%;
  background: transparent;
  border: 1px solid #8a7a2a;
  color: #b8a04a;
  font-family: 'Share Tech Mono', monospace;
  font-size: 10px;
  letter-spacing: 0.2em;
  padding: 10px;
  cursor: pointer;
  text-transform: uppercase;
  transition: all 0.2s;
  margin-bottom: 16px;
}
.logs-compose-btn:hover { border-color: var(--gold); color: var(--gold); }

/* SUPPORT */
.logs-support-msg {
  font-family: 'Share Tech Mono', monospace;
  font-size: 10px;
  color: #4a4530;
  line-height: 2;
  letter-spacing: 0.1em;
  text-align: center;
  padding: 40px 20px;
}

/* AUTH SCREEN */
.logs-auth-screen {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  height: 100%;
  gap: 10px;
  padding: 30px;
}

.logs-auth-title {
  font-family: 'Share Tech Mono', monospace;
  font-size: 10px;
  color: #8a8364;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  margin-bottom: 16px;
  text-align: center;
}

/* LOG VIEW MODAL */
.logs-view-overlay {
  display: none;
  position: absolute;
  inset: 0;
  background: rgba(2,6,12,0.95);
  z-index: 20;
  flex-direction: column;
}
.logs-view-overlay.visible { display: flex; }

.logs-view-header {
  padding: 16px 20px;
  border-bottom: 1px solid #3a3522;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
}

.logs-view-title {
  font-family: 'Oswald', sans-serif;
  font-size: 16px;
  color: var(--gold);
  letter-spacing: 0.05em;
}

.logs-view-meta {
  font-family: 'Share Tech Mono', monospace;
  font-size: 9px;
  color: #8a8364;
  letter-spacing: 0.1em;
  margin-top: 4px;
}

.logs-view-body {
  flex: 1;
  overflow-y: auto;
  padding: 24px 20px;
  font-family: 'Share Tech Mono', monospace;
  font-size: 12px;
  color: #d8c890;
  line-height: 1.9;
  white-space: pre-wrap;
}

/* LOGS NOT AUTH */
.logs-not-auth {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  height: 100%;
  padding: 30px;
}

/* ===== SINGULARITY REGISTRY — SEARCH / FILTER / SORT ===== */
.sing-registry-controls {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  align-items: center;
  margin-bottom: 10px;
}

.sing-registry-search {
  flex: 1 1 220px;
  min-width: 180px;
  background: #111108;
  border: 1px solid #3a3522;
  color: #f0e6c0;
  font-family: 'Share Tech Mono', monospace;
  font-size: 11px;
  padding: 8px 12px;
  outline: none;
  letter-spacing: 0.05em;
  transition: border-color 0.2s;
}
.sing-registry-search:focus { border-color: #f0c419; }
.sing-registry-search::placeholder { color: #6a6448; }

.sing-registry-select {
  background: #111108;
  border: 1px solid #3a3522;
  color: #f0e6c0;
  font-family: 'Share Tech Mono', monospace;
  font-size: 10px;
  padding: 8px 10px;
  outline: none;
  cursor: pointer;
  letter-spacing: 0.05em;
}
.sing-registry-select:focus { border-color: #f0c419; }

.sing-type-checkbox {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-family: 'Share Tech Mono', monospace;
  font-size: 9px;
  letter-spacing: 0.1em;
  color: #8a8364;
  cursor: pointer;
  user-select: none;
}
.sing-type-checkbox input {
  cursor: pointer;
  accent-color: #f0c419;
}
.sing-type-checkbox:hover { color: #f0c419; }

.sing-new-badge {
  display: inline-block;
  background: #f0c419;
  color: #0a0a08;
  font-family: 'Share Tech Mono', monospace;
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.15em;
  padding: 2px 6px;
  border-radius: 2px;
  vertical-align: middle;
  animation: singNewPulse 2s ease-in-out infinite;
}

@keyframes singNewPulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.65; }
}

/* ===== SIR HOOT — SITE ASSISTANT ===== */
.sirhoot-launcher {
  position: fixed;
  bottom: 24px;
  right: 24px;
  width: 60px;
  height: 60px;
  border-radius: 50%;
  background: var(--blue);
  border: 2px solid var(--gold);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  box-shadow: 0 4px 16px rgba(13,34,64,0.35);
  transition: transform 0.15s ease;
  z-index: 999;
  overflow: hidden;
  padding: 0;
}

.sirhoot-icon-img {
  width: 86%;
  height: 86%;
  object-fit: contain;
  pointer-events: none;
  display: block;
}

.sirhoot-launcher:hover { transform: scale(1.06); }

.sirhoot-ping {
  position: absolute;
  top: -2px; right: -2px;
  width: 14px; height: 14px;
  border-radius: 50%;
  background: var(--gold-light);
  border: 2px solid var(--bg);
}

.sirhoot-panel {
  position: fixed;
  bottom: 96px;
  right: 24px;
  width: 340px;
  max-width: calc(100vw - 48px);
  height: 460px;
  max-height: calc(100vh - 140px);
  background: var(--white);
  border: 1px solid var(--border);
  box-shadow: 0 12px 40px rgba(13,34,64,0.25);
  display: flex;
  flex-direction: column;
  overflow: hidden;
  opacity: 0;
  transform: translateY(12px);
  pointer-events: none;
  transition: all 0.18s ease;
  z-index: 998;
}

.sirhoot-panel.open {
  opacity: 1;
  transform: translateY(0);
  pointer-events: auto;
}

.sirhoot-header {
  background: var(--blue);
  color: #e8eef8;
  padding: 14px 16px;
  display: flex;
  align-items: center;
  gap: 10px;
  flex-shrink: 0;
}

.sirhoot-owl-badge {
  width: 34px; height: 34px;
  border-radius: 50%;
  background: var(--gold);
  display: flex; align-items: center; justify-content: center;
  flex-shrink: 0;
  overflow: hidden;
}

.sirhoot-header-text { flex: 1; min-width: 0; }

.sirhoot-name {
  font-family: 'Oswald', sans-serif;
  font-weight: 700;
  font-size: 14px;
  letter-spacing: 0.02em;
}

.sirhoot-status {
  font-size: 10px;
  letter-spacing: 0.1em;
  color: var(--gold-light);
  text-transform: uppercase;
  margin-top: 2px;
}

.sirhoot-close {
  background: none; border: none; color: #c8d4e4;
  font-size: 18px; cursor: pointer; line-height: 1;
  padding: 4px;
}

.sirhoot-log {
  flex: 1;
  overflow-y: auto;
  padding: 14px 16px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.sirhoot-msg {
  max-width: 82%;
  padding: 9px 12px;
  border-radius: 10px;
  font-size: 13px;
  line-height: 1.55;
  font-family: 'Source Serif 4', serif;
}

.sirhoot-msg.bot {
  background: var(--bg);
  border: 1px solid var(--border);
  align-self: flex-start;
  border-bottom-left-radius: 2px;
  color: var(--ink);
}

.sirhoot-msg.user {
  background: var(--blue);
  color: #fff;
  align-self: flex-end;
  border-bottom-right-radius: 2px;
}

.sirhoot-input-row {
  display: flex;
  border-top: 1px solid var(--border);
  flex-shrink: 0;
}

.sirhoot-input-row input {
  flex: 1;
  border: none;
  padding: 12px 14px;
  font-family: 'Source Serif 4', serif;
  font-size: 13px;
  outline: none;
  background: var(--white);
  color: var(--ink);
}

.sirhoot-input-row button {
  border: none;
  background: var(--gold);
  color: var(--blue);
  font-weight: 700;
  padding: 0 18px;
  cursor: pointer;
  font-size: 13px;
  font-family: 'Oswald', sans-serif;
}

.sirhoot-input-row button:hover { background: var(--gold-light); }

@media (max-width: 480px) {
  .sirhoot-panel { right: 12px; bottom: 88px; }
  .sirhoot-launcher { right: 16px; bottom: 16px; }
}


/* ===== IRIS PUBLIC HOMEPAGE REDESIGN (scoped; employee portal styles remain untouched) ===== */
