html[data-theme="classic"]{--iris-paper:#f4f2ee;--iris-ink:#1a1a1a;--iris-muted:#4a4a4a;--iris-navy:#0d2240;--iris-deep:#1a3a6a;--iris-blue:#2a5a9a;--iris-lav:#9caabd;--iris-pale:#d0ccc4;--iris-gold:#c8a820;--iris-line:#d0ccc4}
