/* IRIS design-system pass: extend the approved homepage language to every public tab. */
#publicLayer{--iris-grid:rgba(48,48,123,.055)}
#publicLayer .main-scroll{background:var(--iris-paper);background-image:radial-gradient(var(--iris-grid) 1px,transparent 1px);background-size:14px 14px}
#publicLayer .page:not(#page-home){position:relative;isolation:isolate;min-height:calc(100vh - 180px);padding-top:44px;padding-bottom:76px}
#publicLayer .page:not(#page-home)::before{content:"I.R.I.S. / ARCHIVE INTERFACE";display:block;color:var(--iris-blue);font:700 10px/1.4 Arial, sans-serif;letter-spacing:.18em;margin:0 0 14px;padding-left:14px;border-left:4px solid var(--iris-gold)}
#publicLayer .page:not(#page-home)::after{content:"";position:absolute;z-index:-1;pointer-events:none;top:0;right:0;width:min(34%,340px);height:180px;background:radial-gradient(circle,var(--iris-blue) 1.3px,transparent 1.8px) 0 0/12px 12px;mask-image:linear-gradient(130deg,transparent,#000 65%,transparent);opacity:.16}
#publicLayer .section-header{align-items:center;justify-content:space-between;gap:20px;margin:0 0 28px;padding:0 0 18px;border-bottom:1px solid var(--iris-line);position:relative}
#publicLayer .section-header::after{content:"";position:absolute;bottom:-2px;left:0;width:88px;height:3px;background:var(--iris-gold)}
#publicLayer .section-header h3{font:700 clamp(28px,3vw,42px)/1.05 Arial,Helvetica,sans-serif;letter-spacing:-.04em;color:var(--iris-navy);margin:0}
#publicLayer .section-header>span{display:inline-block;color:var(--iris-blue);font:700 10px/1.5 Arial,sans-serif;letter-spacing:.13em;text-align:right;max-width:45%}
#publicLayer .history-lead,#publicLayer .careers-intro{font-size:17px;line-height:1.75;color:var(--iris-muted);max-width:900px;background:linear-gradient(110deg,rgba(255,255,255,.96),rgba(255,255,255,.62));border:1px solid var(--iris-line);border-left:4px solid var(--iris-blue);padding:24px 28px;margin:0 0 32px}
#publicLayer .timeline{border-left:2px solid var(--iris-line);margin:34px 0 0 18px;padding-left:28px}
#publicLayer .timeline-item{background:rgba(255,255,255,.88);border:1px solid var(--iris-line);border-top:3px solid var(--iris-blue);padding:24px 26px;margin:0 0 20px;box-shadow:5px 5px 0 rgba(155,155,197,.18)}
#publicLayer .timeline-item::before{left:-36px;top:27px;width:12px;height:12px;background:var(--iris-gold);border:3px solid var(--iris-navy);box-sizing:content-box}
#publicLayer .timeline-year{font:700 11px/1.4 Arial,sans-serif;letter-spacing:.12em;color:var(--iris-blue);margin-bottom:10px}
#publicLayer .timeline-item h4,#publicLayer .dept-card h4{font:700 21px/1.2 Arial,sans-serif;letter-spacing:-.02em;color:var(--iris-navy);margin:0 0 10px}
