html:is([data-theme="aqua"],[data-theme="autumn"],[data-theme="dark"],[data-theme="nox"],[data-theme="classified"],[data-theme="clearance"]) #publicLayer :is(.iris-eyebrow,.iris-card-number,.iris-card-icon,.iris-resource-card button,.iris-news-card span,.iris-news-card button,.iris-public-notice button,.iris-about strong,.section-header span){color:var(--iris-accent-text) !important}
